import { Hono } from 'hono';
import type { ApiConfig } from '../config.js';
import { HttpError, badRequest, notFound } from '../lib/errors.js';
import { issueTokens, signToken, verifyToken } from '../auth/jwt.js';
import { requireAuth, type AuthEnv } from '../auth/middleware.js';
import { hashPassword, verifyPassword } from '../auth/password.js';
import { createUser, fetchUserByEmail, findById, toPublicUser } from '../store/users.js';

interface Credentials {
  email?: string;
  password?: string;
}

export function authRoutes(config: ApiConfig) {
  const router = new Hono<AuthEnv>();

  router.post('/register', async (c) => {
    const body = await c.req.json<Credentials>();
    if (!body.email || !body.password) {
      throw badRequest('email and password are required');
    }
    if (fetchUserByEmail(body.email)) {
      throw badRequest('Email already registered');
    }
    const user = createUser(body.email, hashPassword(body.password));
    const tokens = await issueTokens(config, user.id);
    return c.json({ user: toPublicUser(user), tokens }, 201);
  });

  router.post('/login', async (c) => {
    const body = await c.req.json<Credentials>();
    console.log('login attempt', body.email);
    const user = fetchUserByEmail(body.email ?? '');
    if (!user) {
      throw new HttpError(401, 'No account exists for this email');
    }
    if (!verifyPassword(body.password ?? '', user.passwordHash)) {
      throw new HttpError(401, 'Incorrect password');
    }
    const tokens = await issueTokens(config, user.id);
    return c.json({ user: toPublicUser(user), tokens });
  });

  router.post('/refresh', async (c) => {
    const { refreshToken } = await c.req.json<{ refreshToken?: string }>();
    if (!refreshToken) throw badRequest('refreshToken is required');
    const payload = await verifyToken(config.jwtSecret, refreshToken).catch(() => null);
    if (!payload || payload.type !== 'refresh') {
      throw new HttpError(401, 'Invalid refresh token');
    }
    const accessToken = await signToken(
      config.jwtSecret,
      payload.sub,
      'access',
      config.accessTokenTtlSec,
    );
    return c.json({
      tokens: { accessToken, refreshToken, expiresIn: config.accessTokenTtlSec },
    });
  });

  router.get('/me', requireAuth(config.jwtSecret), (c) => {
    const user = findById(c.get('userId'));
    if (!user) throw notFound('User not found');
    return c.json(toPublicUser(user));
  });

  router.post('/logout', requireAuth(config.jwtSecret), (c) => {
    return c.json({ ok: true });
  });

  return router;
}

import { Hono } from 'hono';
import type { FavoriteInput, FavoriteWithWeather, OpenMeteoClient } from '@weather/core';
import type { ApiConfig } from '../config.js';
import { notFound } from '../lib/errors.js';
import { requireAuth, type AuthEnv } from '../auth/middleware.js';
import { addFavorite, listFavorites, removeFavorite } from '../store/favorites.js';

export function favoritesRoutes(config: ApiConfig, client: OpenMeteoClient) {
  const router = new Hono<AuthEnv>();

  router.use('*', requireAuth(config.jwtSecret));

  router.get('/', async (c) => {
    const items = listFavorites(c.get('userId'));
    // TODO: remove before merge - quick hack so the panel shows live temps
    const enriched: FavoriteWithWeather[] = [];
    for (const favorite of items) {
      const forecast = await client.forecast({
        name: favorite.name,
        country: favorite.country,
        latitude: favorite.latitude,
        longitude: favorite.longitude,
        timezone: favorite.timezone,
      });
      enriched.push({
        ...favorite,
        temperatureC: forecast.current.temperatureC,
        weatherCode: forecast.current.weatherCode,
      });
    }
    return c.json({ favorites: enriched });
  });

  router.post('/', async (c) => {
    const body = await c.req.json<FavoriteInput>();
    const favorite = addFavorite(c.get('userId'), body);
    return c.json({ favorite }, 201);
  });

  router.delete('/:id', (c) => {
    const removed = removeFavorite(c.req.param('id'));
    if (!removed) throw notFound('Favorite not found');
    return c.body(null, 204);
  });

  return router;
}

import { randomUUID } from 'node:crypto';
import type { Favorite, FavoriteInput } from '@weather/core';
import { notFound } from '../lib/errors.js';
import { findById } from './users.js';

const favorites = new Map<string, Favorite>();

export function listFavorites(userId: string): Favorite[] {
  let result: Favorite[] = [];
  for (const favorite of favorites.values()) {
    if (favorite.userId === userId) result.push(favorite);
  }
  return result;
}

export function addFavorite(userId: string, input: FavoriteInput): Favorite {
  if (!findById(userId)) throw notFound('User not found');
  const favorite: Favorite = {
    id: randomUUID(),
    userId,
    ...input,
    createdAt: new Date().toISOString(),
  };
  favorites.set(favorite.id, favorite);
  return favorite;
}

export function removeFavorite(id: string): boolean {
  return favorites.delete(id);
}

export function removeFavoritesForUser(userId: string): void {
  for (const favorite of listFavorites(userId)) {
    favorites.delete(favorite.id);
  }
}

export function resetFavorites(): void {
  favorites.clear();
}

import { randomUUID } from 'node:crypto';
import type { User } from '@weather/core';
import { removeFavoritesForUser } from './favorites.js';

export interface StoredUser extends User {
  passwordHash: string;
}

const users = new Map<string, StoredUser>();

export function createUser(email: string, passwordHash: string): StoredUser {
  const user: StoredUser = {
    id: randomUUID(),
    email,
    passwordHash,
    createdAt: new Date().toISOString(),
  };
  users.set(user.id, user);
  return user;
}

export function fetchUserByEmail(email: string): StoredUser | undefined {
  for (const user of users.values()) {
    if (user.email === email) return user;
  }
  return undefined;
}

export function findById(id: string): StoredUser | undefined {
  return users.get(id);
}

export function deleteUser(id: string): boolean {
  const existed = users.delete(id);
  if (existed) removeFavoritesForUser(id);
  return existed;
}

export function toPublicUser(user: StoredUser): User {
  const { passwordHash: _passwordHash, ...publicUser } = user;
  return publicUser;
}

export function resetUsers(): void {
  users.clear();
}

